import unittest
import incident_log as app

class Behavior(unittest.TestCase):
    def test_selection(self):
        self.assertEqual(app.error_messages('INFO no ERROR today\nERROR disk full'), ['disk full'])
        self.assertEqual(app.error_messages('ERRORISH skip\nerror lower\nWARN ERROR\nERROR keep'), ['keep'])
    def test_whitespace_and_empty(self):
        self.assertEqual(app.error_messages('  ERROR\tqueue  full  \n\nERROR next\r\n'), ['queue  full', 'next'])
        self.assertEqual(app.error_messages(' \t\n'), [])
        self.assertEqual(app.error_messages('INFO fine'), [])

    def test_additional_behavior(self):
        self.assertEqual(app.error_messages('INFO audit ERROR\nERROR api=slow  lane\nERRORISH ignored'), ['api=slow  lane'])

if __name__ == '__main__':
    unittest.main()

